def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    sep_r = next((r for r in range(h) if len(set(grid[r])) == 1), None)

    if sep_r is not None:
        first, second = grid[:sep_r], grid[sep_r + 1:]
        bg = Counter(x for row in second for x in row).most_common(1)[0][0]
        return [
            [3 if first[r][c] == second[r][c] else bg
             for c in range(w)]
            for r in range(min(len(first), len(second)))
        ]

    sep_c = next(c for c in range(w)
                 if len({grid[r][c] for r in range(h)}) == 1)
    first = [row[:sep_c] for row in grid]
    second = [row[sep_c + 1:] for row in grid]
    bg = Counter(x for row in second for x in row).most_common(1)[0][0]
    return [
        [3 if first[r][c] == second[r][c] else bg
         for c in range(min(len(first[r]), len(second[r])))]
        for r in range(h)
    ]
